  c.fillStyle = "#ffd04a"; c.fillRect(66, 22 + tilt, 14, 3); const eye = p >= 2 ? "255,40,40" : "60,240,255"; glow(c, 72, 26 + tilt, 20, eye, 1); c.fillStyle = `rgb(${eye})`; c.fillRect(69, 24 + tilt, 6, 4);
