// L16 — ABYSS LEVIATHAN (230x170): colossal deep-sea horror. The lantern bulb is the weak point.
export function drawLeviathan(c, b, t) {
  const p = b.phase || 1, jaw = b.tell === "jaw" ? .75 : b.tell === "roar" ? .5 : .14 + .05 * Math.sin(t * 2), flash = b.tell === "flash";
  c.fillStyle = lin(c, 60, 10, 230, 170, ["#16305a", "#0a1a3a", "#050c1e"]); c.beginPath(); c.ellipse(150, 100, 100, 74, -.05, 0, 7); c.fill();
  for (let i = 0; i < 6; i++) poly(c, [[110 + i * 24, 40 + i * 2], [118 + i * 24, 12 - Math.sin(t * 3 + i) * 5 - i * 2], [130 + i * 24, 40 + i * 2]], "#0e2a5a");
  c.strokeStyle = "rgba(60,120,200,.35)"; c.lineWidth = 2; for (let r = 0; r < 4; r++) for (let i = 0; i < 6; i++) { c.beginPath(); c.arc(110 + i * 22 + (r % 2) * 11, 70 + r * 22, 12, .1, Math.PI - .1); c.stroke(); }
  poly(c, [[196, 90 + Math.sin(t * 3) * 6], [226, 52], [222, 128], [196, 120]], "#0e2a5a"); poly(c, [[150, 130], [190, 168], [120, 150]], "#0e2a5a");
  const pulse = .5 + .5 * Math.sin(t * 4); if (p >= 2) for (let i = 0; i < 14; i++) { const x = 100 + i * 9, y = 90 + Math.sin(i * 1.3) * 28; glow(c, x, y, 12, "80,255,230", .4 + .5 * ((i + Math.floor(t * 6)) % 3 === 0 ? 1 : pulse)); circ(c, x, y, 2, "#aaffee"); }
  const hx = 70, hy = 96;                                                                                                          // jaw hinge
  poly(c, [[hx + 70, hy - 50], [hx - 66, hy - 4 - jaw * 22], [hx - 66, hy + 4], [hx + 70, hy + 4]], "#0e2248");                          // upper jaw
  c.save(); c.translate(hx + 30, hy + 6); c.rotate(jaw); poly(c, [[-96, -2], [40, -8], [44, 40], [-96, 20]], "#0a1a3a"); c.fillStyle = "#050c1e"; c.fillRect(-92, 14, 134, 8);
  for (let i = 0; i < 9; i++) poly(c, [[-92 + i * 14, -2], [-86 + i * 14, -24 - (i % 2) * 8], [-80 + i * 14, -2]], "#e8f0ff"); c.restore();
  const mx = hx + 30 + Math.cos(jaw) * 0; c.fillStyle = lin(c, 0, hy - 2, 0, hy + 30, ["#3a0a1a", "#14040a"]); poly(c, [[hx - 60, hy + 1], [hx + 30, hy - 4], [hx + 30, hy + 6 + Math.sin(jaw) * 70], [hx - 60, hy + 14 + jaw * 50]], c.fillStyle);
  for (let i = 0; i < 9; i++) poly(c, [[hx - 64 + i * 14, hy - 6 - jaw * 16], [hx - 58 + i * 14, hy + 16 + jaw * 10], [hx - 52 + i * 14, hy - 6 - jaw * 16]], "#f4f8ff");
  glow(c, 150, 58, 30, p >= 2 ? "255,70,90" : "255,230,120", .8); circ(c, 150, 58, 13, p >= 2 ? "#ff6a7a" : "#fff0a0"); c.fillStyle = "#000"; c.fillRect(148, 48, 4, 20);
  const lx = 92 + Math.sin(t * 1.5) * 8, ly = -14 + Math.sin(t * 2) * 5; c.strokeStyle = "#0e2248"; c.lineWidth = 6; c.beginPath(); c.moveTo(150, 40); c.quadraticCurveTo(110, -50, lx, ly); c.stroke();
  glow(c, lx, ly + 6, flash ? 120 : 44 + 8 * pulse, "255,240,120", flash ? 1 : .8); circ(c, lx, ly + 6, flash ? 18 : 13, "#fffbd0"); circ(c, lx, ly + 6, 8, "#ffe860");
  c.strokeStyle = "#16305a"; c.lineWidth = 3; for (let i = 0; i < 3; i++) { c.beginPath(); c.moveTo(40, 108 + i * 6); c.quadraticCurveTo(10, 130 + i * 10 + Math.sin(t * 3 + i) * 8, 24, 160 - i * 4); c.stroke(); }
}

// L17 — EXTINCTION (200x200): the comet that ended the dinosaurs. P1 sealed rock face, P2 shell cracks open, P3 white-hot core.
export function drawExtinction(c, b, t) {
  const p = b.phase || 1, cx = 100, cy = 100, R = 76, charge = b.tell === "slam" || b.tell === "nova";
  for (let i = 0; i < 34; i++) { const a = -.5 + hs(i) * 1.2, len = 80 + hs(i + 9) * 90 + Math.sin(t * 9 + i) * 14, w = 10 + hs(i + 4) * 14, bx = cx + 40, by = cy + (hs(i + 2) - .5) * 100; poly(c, [[bx, by - w], [bx + len * Math.cos(a * .3), by + len * Math.sin(a) * .4 - w * .4], [bx, by + w]], i % 3 ? "rgba(255,110,30,.75)" : "rgba(255,200,80,.8)"); }
  glow(c, cx, cy, 150, p >= 3 ? "255,240,200" : "255,120,40", .5 + (charge ? .4 * Math.sin(t * 24) : 0));
  const chunk = (a0, a1, off) => { c.save(); c.translate(Math.cos((a0 + a1) / 2) * off, Math.sin((a0 + a1) / 2) * off); c.beginPath(); c.moveTo(cx, cy); c.arc(cx, cy, R, a0, a1); c.closePath(); c.fillStyle = lin(c, cx - R, cy - R, cx + R, cy + R, ["#6a3a30", "#3a1a14", "#1a0a08"]); c.fill(); c.strokeStyle = "#ff7a1a"; c.lineWidth = 2; c.stroke(); c.restore(); };
  if (p >= 2) { glow(c, cx, cy, 90, "255,180,60", 1); circ(c, cx, cy, 56, p >= 3 ? "#fff6d0" : "#ff6a1a"); circ(c, cx, cy, 40, p >= 3 ? "#ffffff" : "#ffd070"); }
  if (p === 1) { chunk(0, Math.PI * 2, 0); } else if (p === 2) { const o = 12 + 4 * Math.sin(t * 4); chunk(-2.4, -.4, o); chunk(-.4, 1.6, o); chunk(1.6, 3.6, o); } else { const o = 40 + 6 * Math.sin(t * 3); chunk(-2.1, -1.5, o); chunk(.3, .9, o); chunk(2.2, 2.8, o); }
  if (p === 1) { c.strokeStyle = "#ff7a1a"; c.lineWidth = 2.5; for (let i = 0; i < 7; i++) { const a = hs(i) * 6.283; c.beginPath(); c.moveTo(cx + Math.cos(a) * 14, cy + Math.sin(a) * 14); for (let j = 1; j < 5; j++) c.lineTo(cx + Math.cos(a + (hs(i + j) - .5) * .5) * (14 + j * 15), cy + Math.sin(a + (hs(i + j) - .5) * .5) * (14 + j * 15)); c.stroke(); }
    for (const [x, y, r] of [[60, 70, 10], [130, 140, 12], [70, 140, 7], [140, 58, 8]]) { circ(c, x, y, r, "rgba(0,0,0,.3)"); circ(c, x + 1, y + 1, r - 2, "rgba(255,120,40,.15)"); } }
  const ey = p === 1 ? 88 : 96, fx = p >= 3 ? 70 : 62;                                                                              // the face
  const fire = charge ? "255,255,200" : "255,160,40"; glow(c, fx, ey, 26, fire, 1); glow(c, fx + 38, ey + 2, 26, fire, 1);
  poly(c, [[fx - 12, ey - 8], [fx + 8, ey - 2], [fx + 8, ey + 6], [fx - 8, ey + 6]], "#fff0a0"); poly(c, [[fx + 28, ey - 2], [fx + 52, ey - 10], [fx + 48, ey + 6], [fx + 30, ey + 6]], "#fff0a0");
  poly(c, [[fx - 16, ey - 16], [fx + 10, ey - 6], [fx + 10, ey - 11], [fx - 14, ey - 22]], "#1a0804"); poly(c, [[fx + 56, ey - 20], [fx + 28, ey - 8], [fx + 28, ey - 13], [fx + 54, ey - 26]], "#1a0804");
  const mo = charge ? 16 : 6 + 3 * Math.sin(t * 3); poly(c, [[fx - 8, ey + 24], [fx + 14, ey + 24 - mo], [fx + 26, ey + 28], [fx + 40, ey + 24 - mo], [fx + 58, ey + 24], [fx + 44, ey + 30 + mo], [fx + 26, ey + 34 + mo], [fx + 8, ey + 30 + mo]], "#ff5a10"); for (let i = 0; i < 6; i++) poly(c, [[fx - 2 + i * 10, ey + 25], [fx + 3 + i * 10, ey + 31], [fx + 8 + i * 10, ey + 25]], "#1a0804");
  for (let i = 0; i < 6; i++) { const a = t * (.8 + i * .12) + i * 1.1, rr = 96 + (i % 3) * 10; poly(c, [[cx + Math.cos(a) * rr - 6, cy + Math.sin(a) * rr * .7 - 5], [cx + Math.cos(a) * rr + 5, cy + Math.sin(a) * rr * .7 - 6], [cx + Math.cos(a) * rr + 6, cy + Math.sin(a) * rr * .7 + 5], [cx + Math.cos(a) * rr - 5, cy + Math.sin(a) * rr * .7 + 6]], "#3a1a14"); }
}
